const User = require('../models/User');
const { isPasswordValid } = require('../config/utils');

// GET /admin - List all accounts across all roles
exports.list = async (req, res, next) => {
  try {
    // Exclude password hashes when fetching all users
    const users = await User.find({}).lean();
    res.status(200).json(users);
  } catch (err) {
    next(err);
  }
};

// POST /admin/create-admin - Create an admin user account
exports.createAdmin = async (req, res, next) => {
  try {
    const { firstName = '', lastName = '', username, password, email = '' } = req.body || {};

    if (!username || !password) {
      return res.status(400).json({ error: 'username and password are required' });
    }

    if (await User.exists({ username: String(username) })) {
      return res.status(409).json({ error: 'A user with that username already exists' });
    }

    const passwordRet = isPasswordValid(password);
    if (!passwordRet.valid) {
      return res.status(400).json({ error: passwordRet.error });
    }

    // Explicitly set role to 'admin'
    const user = await User.create({
      firstName: String(firstName),
      lastName: String(lastName),
      username: String(username),
      passwordHash: String(password),
      email: String(email),
      role: 'admin'
    });

    res
      .status(201)
      .location(`/api/users/${user._id}`)
      .json({ message: 'Admin account created successfully', user });
  } catch (err) {
    next(err);
  }
};

