// POST /admin/users/:userId/password - Admin reset/change a user's password
exports.changePassword = async (req, res, next) => {
  try {
    const { userId } = req.params;
    const { password } = req.body || {};

    if (!password) {
      return res.status(400).json({ error: 'New password is required' });
    }

    const passwordRet = isPasswordValid(password);
    if (!passwordRet.valid) {
      return res.status(400).json({ error: passwordRet.error });
    }

    const user = await User.findById(userId);
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Setting passwordHash triggers the model's pre-save hashing middleware
    user.passwordHash = String(password);
    await user.save();

    res.status(200).json({ message: 'Password updated successfully' });
  } catch (err) {
    next(err);
  }
};